<script setup lang="ts">
import { computed } from 'vue'
import { LOTTERIES } from '../config/lottery'
import { useGameStore } from '../stores/game'
const store=useGameStore();const a=()=>store.game.automation
const lotteryOptions = computed(() => LOTTERIES.filter(item => item.price > 0))
const lotteryIndex = computed(() => Math.max(0, lotteryOptions.value.findIndex(item => item.id === a().ticketType)))
function onLotteryChange(event: any) { const item = lotteryOptions.value[Number(event.detail.value)]; if (item) store.setAutomation('ticketType', item.id) }
function onNumberChange(key: 'purchaseBudget' | 'reserveCoins', event: any) { store.setAutomation(key, Math.max(0, Number(event.detail.value) || 0)) }
</script>
<template><view class="page"><view class="page-heading"><view><text class="eyebrow">AUTOMATION FACTORY</text><text>自动化控制台</text><view>从手动刮奖走向自动化彩票工厂。</view></view><button class="btn primary" @tap="store.toggleAutomation()">{{a().enabled?'⏸ 暂停经营':'▶ 启动经营'}}</button></view><view class="panel automation-status"><view><text class="eyebrow">FACTORY STATUS</text><text>{{a().enabled?'自动化生产线运行中':'生产线已暂停'}}</text><view>{{a().enabled?'自动化任务将根据解锁能力持续执行。':'启动后将按当前设置执行自动购票、刮奖与提交。'}}</view></view><view class="status-orb" :class="{running:a().enabled}">🤖</view></view><view class="automation-grid"><view class="panel automation-card"><view class="automation-icon">🎟️</view><text>自动提交</text><view>自动将已刮开的中奖彩票送入验票队列。</view><text class="unlock-label">自动化天赋 Lv.1 解锁</text><button class="switch" :class="{on:a().autoSubmit}" @tap="store.toggleAuto('autoSubmit')">{{a().autoSubmit?'已开启':'已关闭'}}</button></view><view class="panel automation-card"><view class="automation-icon">🪙</view><text>自动领取</text><view>验票完成后自动将奖金结算到金币余额。</view><text class="unlock-label">自动化天赋 Lv.2 解锁</text><text class="enabled-label">{{store.game.talents.automation>=2?'已解锁 · 自动运行':'尚未解锁'}}</text></view><view class="panel automation-card"><view class="automation-icon">✨</view><text>自动刮奖</text><view>自动处理新购入的彩票，完成全部刮奖区域。</view><text class="unlock-label">自动化天赋 Lv.3 解锁</text><button class="switch" :class="{on:a().autoScratch}" @tap="store.toggleAuto('autoScratch')">{{a().autoScratch?'已开启':'已关闭'}}</button></view><view class="panel automation-card"><view class="automation-icon">🏭</view><text>自动购票</text><view>按预算与保留金币策略自动购买指定类型的彩票。</view><text class="unlock-label">自动化天赋 Lv.5 解锁</text><button class="switch" :class="{on:a().autoBuy}" @tap="store.toggleAuto('autoBuy')">{{a().autoBuy?'已开启':'已关闭'}}</button><view class="automation-settings"><view class="setting-field"><text>彩票类型</text><picker mode="selector" :range="lotteryOptions" range-key="name" :value="lotteryIndex" @change="onLotteryChange"><view class="picker-value">{{ lotteryOptions[lotteryIndex]?.name || '请选择' }}　⌄</view></picker></view><view class="setting-field"><text>总预算</text><input type="number" min="0" :value="a().purchaseBudget" @input="onNumberChange('purchaseBudget',$event)" /></view><view class="setting-field"><text>最低保留金币</text><input type="number" min="0" :value="a().reserveCoins" @input="onNumberChange('reserveCoins',$event)" /></view><text>已使用预算：{{a().spentBudget.toLocaleString()}} / {{a().purchaseBudget.toLocaleString()}}</text></view></view></view><view class="panel automation-note">🔒 完整自动化生产线需要自动化天赋达到 Lv.8。自动化暂停不会取消已经进入验票队列的任务。</view></view></template>